INSERT INTO public.flashcards
  (id1, cn, pinyin, vocabulary, pinyin_vocab, th, sentence_test, translate, pinyin_sentence)
VALUES
(1251, '泡', 'pào', '泡泡', 'pào pào', 'ฟองสบู่', '我喜欢在公园里吹泡泡。', 'ฉันชอบเป่าฟองสบู่ในสวนสาธารณะ', 'wǒ xǐ huān zài gōng yuán lǐ chuī pào pào'),
(1252, '姓', 'xìng', '姓名', 'xìng míng', 'ชื่อ-นามสกุล', '我们要在卷子上写上自己的姓名。', 'เราต้องเขียนชื่อ-นามสกุลของตัวเองลงบนข้อสอบ', 'wǒ men yào zài juàn zi shàng xiě shàng zì jǐ de xìng míng'),
(1253, '氏', 'shì', '姓氏', 'xìng shì', 'นามสกุล/แซ่', '在我们国家，有很多不同的姓氏。', 'ในประเทศเรามีนามสกุลที่แตกต่างกันมากมาย', 'zài wǒ men guó jiā, yǒu hěn duō bù tóng de xìng shì'),
(1254, '邻', 'lín', '邻居', 'lín jū', 'เพื่อนบ้าน', '我的邻居是个热心的老奶奶。', 'เพื่อนบ้านของฉันเป็นคุณยายที่ใจดีมีน้ำใจ', 'wǒ de lín jū shì gè rè xīn de lǎo nǎi nai'),
(1255, '龟', 'guī', '乌龟', 'wū guī', 'เต่า', '池塘里有一只小乌龟。', 'ในสระน้ำมีเต่าตัวเล็กอยู่ตัวหนึ่ง', 'chí táng lǐ yǒu yì zhī xiǎo wū guī'),
(1256, '性', 'xìng', '性格', 'xìng gé', 'นิสัย/บุคลิก', '那个女孩的性格很开朗。', 'เด็กหญิงคนนั้นนิสัยร่าเริงแจ่มใส', 'nà ge nǚ hái de xìng gé hěn kāi lǎng'),
(1257, '瓢', 'piáo', '瓢泼', 'piáo pō', '(ฝน)เทกระหน่ำ', '天空下起了瓢泼大雨。', 'ท้องฟ้าเริ่มมีฝนตกลงมาอย่างหนักเทกระหน่ำ', 'tiān kōng xià qǐ le piáo pō dà yǔ'),
(1258, '炸', 'zhá', '油炸', 'yóu zhá', 'ทอด (น้ำมัน)', '油炸食品不健康。', 'อาหารทอดไม่ดีต่อสุขภาพ', 'yóu zhá shí pǐn bù jiàn kāng'),
(1259, '甘', 'gān', '甘草', 'gān cǎo', 'ชะเอม', '甘草可以用来做药。', 'ชะเอมใช้ทำยาได้', 'gān cǎo kě yǐ yòng lái zuò yào'),
(1260, '舌', 'shé', '舌头', 'shé tóu', 'ลิ้น', '变色龙的舌头很长。', 'ลิ้นของกิ้งก่าคาเมเลียนยาวมาก', 'biàn sè lóng de shé tóu hěn cháng'),
(1261, '毁', 'huǐ', '毁灭', 'huǐ miè', 'ทำลายล้าง/พินาศ', '这个美丽的地方被地震毁灭了。', 'สถานที่ที่งดงามแห่งนี้ถูกแผ่นดินไหวทำลายจนพินาศ', 'zhè ge měi lì de dì fāng bèi dì zhèn huǐ miè le'),
(1262, '掩', 'yǎn', '掩埋', 'yǎn mái', 'ฝังกลบ', '山下的房子被泥石流掩埋了。', 'บ้านเชิงเขาถูกดินโคลนถล่มฝังกลบไปแล้ว', 'shān xià de fáng zi bèi ní shí liú yǎn mái le'),
(1263, '守', 'shǒu', '守卫', 'shǒu wèi', 'ปกป้อง/อารักขา', '解放军战士守卫着国家。', 'เหล่าทหารปลดแอกปกป้องประเทศชาติ', 'jiě fàng jūn zhàn shì shǒu wèi zhe guó jiā'),
(1264, '曹', 'cáo', '曹丘', 'cáo qiū', 'แซ่เฉาชิว (นามสกุลหายาก)', '曹丘是一个非常少见的姓氏。', 'เฉาชิวเป็นนามสกุลที่หายากมาก', 'cáo qiū shì yí gè fēi cháng shǎo jiàn de xìng shì'),
(1265, '玲', 'líng', '玲珑', 'líng lóng', 'เล็กกระทัดรัด/ประณีต', '我有一个小巧玲珑的工艺品。', 'ฉันมีงานฝีมือชิ้นเล็กกระทัดรัดประณีตอยู่ชิ้นหนึ่ง', 'wǒ yǒu yí gè xiǎo qiǎo líng lóng de gōng yì pǐn'),
(1266, '傻', 'shǎ', '傻笑', 'shǎ xiào', 'ยิ้มแหะๆ/หัวเราะเซ่อๆ', '小明高兴地傻笑起来。', 'เสี่ยวหมิงดีใจจนหัวเราะแหะๆ ออกมา', 'xiǎo míng gāo xìng de shǎ xiào qǐ lái'),
(1267, '善', 'shàn', '善意', 'shàn yì', 'เจตนาดี/ความหวังดี', '那个访客是带着善意来的。', 'แขกคนนั้นมาด้วยความหวังดี', 'nà ge fǎng kè shì dài zhe shàn yì lái de'),
(1268, '扛', 'káng', '扛枪', 'káng qiāng', 'แบกปืน', '照片里那个扛枪的人是我的爷爷。', 'คนที่แบกปืนอยู่ในรูปคือคุณปู่ของฉัน', 'zhào piàn lǐ nà ge káng qiāng de rén shì wǒ de yé ye'),
(1269, '窝', 'wō', '鸟窝', 'niǎo wō', 'รังนก', '树上有一个鸟窝。', 'บนต้นไม้มีรังนกอยู่รังหนึ่ง', 'shù shàng yǒu yí gè niǎo wō'),
(1270, '粮', 'liáng', '粮食', 'liáng shí', 'เสบียง/ธัญญาหาร', '我们需要很多粮食。', 'เราต้องการเสบียงอาหารจำนวนมาก', 'wǒ men xū yào hěn duō liáng shí'),
(1271, '翠', 'cuì', '翠绿', 'cuì lǜ', 'เขียวสด', '小羊们正在翠绿的草原上吃草。', 'ลูกแกะกำลังกินหญ้าอยู่บนทุ่งหญ้าเขียวสด', 'xiǎo yáng men zhèng zài cuì lǜ de cǎo yuán shàng chī cǎo'),
(1272, '拨', 'bō', '拨号', 'bō hào', 'กดหมายเลข/หมุนโทรศัพท์', '电话上绿色的按键是拨号号键。', 'ปุ่มสีเขียวบนโทรศัพท์คือปุ่มกดหมายเลข', 'diàn huà shàng lǜ sè de àn jiàn shì bō hào hào jiàn'),
(1273, '咕', 'gū', '咕咕', 'gū gū', 'เสียงจู๋ๆ (นกเขา)', '鸽子会发出咕咕的叫声。', 'นกพิราบจะส่งเสียงร้องจู๋ๆ', 'gē zi huì fā chū gū gū de jiào shēng'),
(1274, '咚', 'dōng', '咕咚', 'gū dōng', 'เสียงอึกๆ (ดื่มน้ำ)', '一群大象在咕咚咕咚地喝水。', 'ช้างฝูงหนึ่งกำลังดื่มน้ำเสียงอึกๆ', 'yì qún dà xiàng zài gū dōng gū dōng de hē shuǐ'),
(1275, '掰', 'bāi', '掰开', 'bāi kāi', 'หัก/แกะออก (ด้วยมือ)', '我帮爷爷把这个水果掰开了。', 'ฉันช่วยคุณปู่แกะผลไม้ลูกนี้ออก', 'wǒ bāng yé ye bǎ zhè ge shuǐ guǒ bāi kāi le'),
(1276, '炮', 'pào', '鞭炮', 'biān pào', 'ประทัด', '过年的时候要放鞭炮。', 'ตอนปีใหม่ต้องจุดประทัด', 'guò nián de shí hòu yào fàng biān pào'),
(1277, '端', 'duān', '端正', 'duān zhèng', 'ตรง/ถูกต้องเรียบร้อย', '我们的坐姿要端正。', 'ท่านั่งของเราต้องตรง', 'wǒ men de zuò zī yào duān zhèng'),
(1278, '绳', 'shéng', '头绳', 'tóu shéng', 'ยางรัดผม/เชือกมัดผม', '我今天用的头绳是红色的。', 'ยางรัดผมที่ฉันใช้วันนี้เป็นสีแดง', 'wǒ jīn tiān yòng de tóu shéng shì hóng sè de'),
(1279, '偏', 'piān', '偏心', 'piān xīn', 'ลำเอียง/เข้าข้าง', '老师对我们很公平，一点都不偏心。', 'คุณครูยุติธรรมกับเรามาก ไม่ลำเอียงเลยแม้แต่น้อย', 'lǎo shī duì wǒ men hěn gōng píng, yì diǎn dōu bù piān xīn'),
(1280, '鞭', 'biān', '马鞭', 'mǎ biān', 'แส้ม้า', '爷爷有一根精美的马鞭。', 'คุณปู่มีแส้ม้าที่ประณีตงดงามอยู่อันหนึ่ง', 'yé ye yǒu yì gēn jīng měi de mǎ biān'),
(1281, '萍', 'píng', '浮萍', 'fú píng', 'แหน (พืชน้ำ)', '水池里漂满了绿色的浮萍。', 'ในสระน้ำมีแหนสีเขียวลอยเต็มไปหมด', 'shuǐ chí lǐ piāo mǎn le lǜ sè de fú píng'),
(1282, '严', 'yán', '严格', 'yán gé', 'เข้มงวด', '李老师虽然很严格，但我们都很喜欢她。', 'ครูหลี่ถึงจะเข้มงวดมาก แต่พวกเราก็ชอบท่านมาก', 'lǐ lǎo shī suī rán hěn yán gé, dàn wǒ men dōu hěn xǐ huān tā'),
(1283, '幼', 'yòu', '幼儿园', 'yòu ér yuán', 'โรงเรียนอนุบาล', '幼儿园里有好多小朋友。', 'ในโรงเรียนอนุบาลมีเด็กๆ มากมาย', 'yòu ér yuán lǐ yǒu hǎo duō xiǎo péng yǒu'),
(1284, '义', 'yì', '意义', 'yì yì', 'ความหมาย/คุณค่า', '我们过了一个有意义的夏天。', 'เราผ่านฤดูร้อนที่มีความหมายไปหนึ่งฤดู', 'wǒ men guò le yí gè yǒu yì yì de xià tiān'),
(1285, '迁', 'qiān', '迁就', 'qiān jiù', 'ตามใจ/อะลุ่มอล่วย', '我们不要迁就自己的错误。', 'เราอย่าตามใจข้อผิดพลาดของตัวเอง', 'wǒ men bú yào qiān jiù zì jǐ de cuò wù'),
(1286, '支', 'zhī', '开支', 'kāi zhī', 'รายจ่าย/ค่าใช้จ่าย', '妈妈会记下家里的开支。', 'แม่จะจดบันทึกรายจ่ายในบ้าน', 'mā mā huì jì xià jiā lǐ de kāi zhī'),
(1287, '孤', 'gū', '孤独', 'gū dú', 'โดดเดี่ยว/เหงา', '有朋友就不会觉得孤独。', 'มีเพื่อนก็จะไม่รู้สึกโดดเดี่ยว', 'yǒu péng yǒu jiù bú huì jué de gū dú'),
(1288, '凝', 'níng', '凝望', 'níng wàng', 'จ้องมอง/เพ่งมอง', '他呆呆地凝望着天空。', 'เขาจ้องมองท้องฟ้าอย่างเหม่อลอย', 'tā dāi dāi de níng wàng zhe tiān kōng'),
(1289, '锻', 'duàn', '锻造', 'duàn zào', 'ตีขึ้นรูป (โลหะ)', '锻造是一种加工方法。', 'การตีขึ้นรูปเป็นวิธีการแปรรูปอย่างหนึ่ง', 'duàn zào shì yì zhǒng jiā gōng fāng fǎ'),
(1290, '炼', 'liàn', '锻炼', 'duàn liàn', 'ออกกำลังกาย/ฝึกฝน', '好身体是需要锻炼的。', 'ร่างกายที่ดีต้องอาศัยการออกกำลังกาย', 'hǎo shēn tǐ shì xū yào duàn liàn de'),
(1291, '词', 'cí', '诗词', 'shī cí', 'บทกวี/กลอน', '小白很聪明，会背很多诗词了。', 'เสี่ยวไป๋ฉลาดมาก ท่องบทกวีได้หลายบทแล้ว', 'xiǎo bái hěn cōng míng, huì bèi hěn duō shī cí le'),
(1292, '爬', 'pá', '爬山', 'pá shān', 'ปีนเขา/เดินเขา', '我和妈妈准备去爬山。', 'ฉันกับแม่เตรียมตัวจะไปปีนเขา', 'wǒ hé mā mā zhǔn bèi qù pá shān'),
(1293, '酷', 'kù', '冷酷', 'lěng kù', 'เย็นชา/เหี้ยมเกรียม', '那个男生看起来很冷酷。', 'ผู้ชายคนนั้นดูเย็นชามาก', 'nà ge nán shēng kàn qǐ lái hěn lěng kù'),
(1294, '棍', 'gùn', '冰棍', 'bīng gùn', 'ไอติมแท่ง', '大家都喜欢吃冰棍。', 'ทุกคนชอบกินไอติมแท่ง', 'dà jiā dōu xǐ huān chī bīng gùn'),
(1295, '具', 'jù', '玩具', 'wán jù', 'ของเล่น', '弟弟有好多好玩的玩具。', 'น้องชายมีของเล่นสนุกๆ เยอะแยะ', 'dì di yǒu hǎo duō hǎo wán de wán jù'),
(1296, '通', 'tōng', '交通', 'jiāo tōng', 'การจราจร/คมนาคม', '北京是个交通便利的城市。', 'ปักกิ่งเป็นเมืองที่การคมนาคมสะดวก', 'běi jīng shì gè jiāo tōng biàn lì de chéng shì'),
(1297, '耐', 'nài', '耐心', 'nài xīn', 'อดทน/ใจเย็น', '老师正十分耐心地和学生谈话。', 'คุณครูกำลังพูดคุยกับนักเรียนอย่างอดทนใจเย็น', 'lǎo shī zhèng shí fēn nài xīn de hé xué shēng tán huà'),
(1298, '鹰', 'yīng', '老鹰', 'lǎo yīng', 'เหยี่ยว/อินทรี', '老鹰会用自己的爪子去捉小动物。', 'เหยี่ยวจะใช้กรงเล็บของมันจับสัตว์เล็กๆ', 'lǎo yīng huì yòng zì jǐ de zhuǎ zi qù zhuō xiǎo dòng wù'),
(1299, '翔', 'xiáng', '飞翔', 'fēi xiáng', 'โบยบิน', '小鸟在天空飞翔。', 'นกน้อยโบยบินอยู่บนท้องฟ้า', 'xiǎo niǎo zài tiān kōng fēi xiáng'),
(1300, '辛', 'xīn', '辛苦', 'xīn kǔ', 'เหน็ดเหนื่อย/ตรากตรำ', '农民伯伯劳动非常辛苦。', 'ลุงชาวนาทำงานเหน็ดเหนื่อยมาก', 'nóng mín bó bo láo dòng fēi cháng xīn kǔ');
